function fullVowelSlices(word: string): number {
  const vowels = "aeiou";
  let count = 0;
  for (let i = 0; i < word.length; i++) {
    const seen = new Set<string>();
    for (let j = i; j < word.length && vowels.includes(word[j]); j++) {
      seen.add(word[j]);
      if (seen.size === 5) count++;
    }
  }
  return count;
}

