function fullVowelSlices(word: string): number {
  let last = new Map<string, number>();
  let start = 0, count = 0;
  for (let r = 0; r < word.length; r++) {
    const c = word[r];
    if (!"aeiou".includes(c)) {
      start = r + 1;
      last = new Map();
      continue;
    }
    last.set(c, r);
    if (last.size === 5) count += Math.min(...last.values()) - start + 1;
  }
  return count;
}

